mapper.select:
select a.id, a.tenant_id, a.plan_no, a.warehouse_code, a.warehouse_name, a.status, a.factory_code, a.handle_state, a.stock_freeze_mode, a.cancel_reason, a.cancel_by, a.cancel_time, a.create_time, a.update_time, a.create_by, a.update_by, a.del_flag from wms_inside_inventory_plan a where a.del_flag = '0' AND a.tenant_id = #{params.tenantId} AND a.factory_code = #{params.factoryCode}
and a.plan_no like concat('%', #{params.planNo}, '%')
and a.warehouse_code = #{params.warehouseCode}
and a.status = #{params.status}
and a.handle_state = #{params.handleState}
and exists ( select 1 from wms_inside_inventory_plan_detail b where b.plan_id = a.id AND b.tenant_id = a.tenant_id AND b.factory_code = a.factory_code AND b.del_flag = '0'
and b.mat_code like concat('%', #{params.matCode}, '%')
and b.mat_name like concat('%', #{params.matName}, '%')
)
order by a.create_time desc, a.id desc
